    local lastDay = CfUtils.GetLocalData("FishLastEnter")
    if checkNumber(lastDay) ~= checkNumber(t.day) then
        self:OnBtnTask()
        CfUtils.WriteLocalData("FishLastEnter", checkNumber(t.day))
    end
end

